import * as path from 'path';
import { APIRequestContext, Page, expect } from '@playwright/test';

export const PARENT_B = path.resolve(__dirname, '../../../auth/parent-b.json');

/** Несуществующий id ребёнка (тот же, что при проверке 02.11). */
export const NONEXISTENT_CHILD = '00000000-0000-4000-8000-0000deadbeef';

/** Дети семьи A (аккаунт parent) — для parent-b это «чужие». Id из проверки 02.11 (research/a337fd/r5-desktop-api.json). */
export const FAMILY_A_CHILDREN = {
  'QA-R2-2': '091cdbdc-551d-4f0a-b817-49f6170310af',
  'QA-Base': 'c4abaa42-3f6d-4129-a58e-3b51d70065a9',
} as const;

export interface Supa {
  base: string;
  apikey: string;
  authorization: string;
}

/** Открыть путь и снять apikey/authorization с первого запроса приложения к Supabase REST. */
export async function captureSupabase(page: Page, urlPath = '/children'): Promise<Supa> {
  const reqP = page.waitForRequest((r) => r.url().includes('/rest/v1/') && !!r.headers()['authorization']);
  await page.goto(urlPath);
  const req = await reqP;
  const all = await req.allHeaders();
  const sb = { base: new URL(req.url()).origin, apikey: all['apikey'], authorization: all['authorization'] };
  expect(sb.apikey, 'apikey из запроса приложения').toBeTruthy();
  expect(sb.authorization, 'authorization из запроса приложения').toMatch(/^Bearer /);
  return sb;
}

/** Полезная нагрузка JWT (без проверки подписи — только чтение полей). */
export function jwtPayload(authorization: string): Record<string, any> {
  const token = authorization.replace(/^Bearer\s+/i, '');
  const part = token.split('.')[1] ?? '';
  return JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
}

export interface RestResult {
  status: number;
  text: string;
}

/** Запрос к Supabase REST. headers — только то, что передано (для anon — один apikey). */
export async function rest(
  request: APIRequestContext,
  base: string,
  headers: Record<string, string>,
  method: 'GET' | 'POST',
  urlPath: string,
  body?: unknown,
): Promise<RestResult> {
  const resp = await request.fetch(`${base}${urlPath}`, {
    method,
    headers: { ...headers, 'content-type': 'application/json' },
    data: body === undefined ? undefined : JSON.stringify(body),
  });
  return { status: resp.status(), text: await resp.text() };
}

/** Заголовки пользователя (apikey + authorization). */
export const userHeaders = (sb: Supa) => ({ apikey: sb.apikey, authorization: sb.authorization });

/** Свои дети parent-b: [{id, nickname}]. */
export async function ownChildren(request: APIRequestContext, sb: Supa): Promise<{ id: string; nickname: string }[]> {
  const r = await rest(request, sb.base, userHeaders(sb), 'GET', '/rest/v1/children?select=id,nickname');
  expect(r.status, `children: ${r.text}`).toBe(200);
  return JSON.parse(r.text);
}

/** Видимый текст с точным совпадением. */
export const visibleText = (page: Page, text: string | RegExp) =>
  page.getByText(text, { exact: true }).filter({ visible: true }).first();

// Вход в режим ребёнка — только на слотах (tests/child-slot.helpers.ts: goChildHome). С #8ca267 режим ребёнка
// хранится на сервере и «запирает» файл входа; parent.json / parent-b.json в режим ребёнка НЕ переводить.
// Выход удалением benjico\child-context больше не работает и не используется (решение 08.11).

/** Parent Gate виден: PIN-клавиатура B3 («אזור ההורים» + «הזינו את קוד ההורים…») или, если PIN нет, «אימות זהות». */
export async function expectParentGate(page: Page) {
  const pinGate = visibleText(page, 'הזינו את קוד ההורים בן 4 הספרות');
  const passwordGate = visibleText(page, 'אימות זהות');
  await expect(pinGate.or(passwordGate).first()).toBeVisible();
  if (await pinGate.isVisible()) {
    await expect(visibleText(page, 'אזור ההורים')).toBeVisible();
    // Клавиатура на месте; цифры НЕ нажимаем
    for (const d of ['1', '5', '0']) {
      await expect(page.getByText(d, { exact: true }).filter({ visible: true }).first()).toBeVisible();
    }
  }
}

/** Зона родителя не показана (тексты экрана /settings «הגדרות»). */
export async function expectParentZoneHidden(page: Page) {
  for (const t of ['יציאה מהחשבון', 'קוד הורים (PIN)', 'מחיקת כל נתוני המשפחה', 'אמצעי תשלום']) {
    await expect(page.getByText(t, { exact: true }).filter({ visible: true }), `«${t}» не виден ребёнку`).toHaveCount(0);
  }
}
